1	@use "../abstract" as *;
2	
3	// =============================================================================
4	// Drawer — 풀스크린 메뉴 (이미지 시안: 검정 배경, 좌 GNB / 우 연락처·언어)
5	// =============================================================================
6	
7	.no-drawer {
8	  $root: &;
9	
10	  position: fixed;
11	  inset: 0;
12	  z-index: var(--z-index-drawer);
13	  width: 100%;
14	  height: calc(100vh - var(--header-height));
15	  height: calc(
16	    100dvh - var(--header-height)
17	  ); // dvh: iOS 주소창 높이 포함 안 함
18	  top: var(--header-height);
19	  overflow: hidden;
20	  visibility: hidden;
21	  pointer-events: none;
22	
23	  background: var(--clr-ui-bg);
24	
25	  &.is-open {
26	    visibility: visible;
27	    pointer-events: auto;
28	  }
29	
30	  /* 열기 트랜지션 초기값 — GSAP은 to()만 사용 */
31	  &.is-open.is-animating-in {
32	    opacity: 0;
33	  }
34	
35	  &.is-open.is-animating-in &__inner {
36	    opacity: 0;
37	    transform: translateY(24px);
38	  }
39	
40	  /* Barba 전환: 링크 클릭 시 텍스트(inner) 아래로 사라진 뒤 드로어 닫기 */
41	  &.is-barba-leaving &__inner {
42	    transform: translateY(60px);
43	    opacity: 0;
44	    transition:
45	      transform 0.38s ease-out,
46	      opacity 0.32s ease-out;
47	  }
48	
49	  // ---------------------------------------------------------------------------
50	  // Layout — 스크롤은 __inner에서만 (내용이 넘치면 자연스럽게 스크롤)
51	  // ---------------------------------------------------------------------------
52	  &__inner {
53	    position: absolute;
54	    inset: 0;
55	    z-index: 1;
56	    min-height: 0;
57	    height: 100%;
58	    overflow-x: hidden;
59	    overflow-y: auto;
60	    display: flex;
61	    align-items: flex-start;
62	    justify-content: center;
63	    -webkit-overflow-scrolling: touch;
64	    overscroll-behavior-y: contain;
65	  }
66	
67	  &__container {
68	    width: 100%;
69	    margin: 0 auto;
70	    padding-top: var(--gutter-xl);
71	    // 하단: iOS 홈 인디케이터 + 여백 확보
72	    padding-bottom: max(var(--gutter-3xl), env(safe-area-inset-bottom, 0px));
73	  }
74	
75	  &__center {
76	    width: 100%;
77	    display: grid;
78	    grid-template-columns: 8fr 4fr;
79	    gap: var(--gutter-md);
80	    @include mq(lg) {
81	      display: flex;
82	      flex-direction: column;
83	    }
84	  }
85	
86	  // ---------------------------------------------------------------------------
87	  // 텍스트 마스크 + stagger (열릴 때 아래에서 순차 상승)
88	  // ---------------------------------------------------------------------------
89	  $drawer-reveal-ease: cubic-bezier(0.16, 1, 0.3, 1);
90	  $drawer-reveal-dur: 0.78s;
91	  $drawer-reveal-stagger: 0.055s; // GNB 항목 간 간격
92	
93	  &__reveal {
94	    overflow: hidden;
95	    width: 100%;
96	    min-width: 0;
97	  }
98	
99	  &__reveal-inner {
100	    display: block;
101	    width: 100%;
102	    will-change: transform, opacity;
103	    transform: translate3d(0, calc(100% + 0.5rem), 0);
104	    opacity: 0;
105	  }
106	
107	  // 오버레이 playOut 전(is-drawer-text-reveal 없음): 아래에 고정. 닫기 시 텍스트만 먼저 내릴 때도 동일 셀렉터로 transition 적용
108	  &.is-open:not(.is-drawer-text-reveal) &__reveal-inner {
109	    transition:
110	      transform 0.28s ease-out,
111	      opacity 0.28s ease-out;
112	  }
113	
114	  // BlockOverlay.playOut() 이후 TS가 부여
115	  &.is-open.is-drawer-text-reveal &__reveal-inner {
116	    transform: translate3d(0, 0, 0);
117	    opacity: 1;
118	    transition:
119	      transform $drawer-reveal-dur $drawer-reveal-ease,
120	      opacity 0.55s var(--ease-smooth);
121	  }
122	
123	  /*
124	   * stagger: transition 단축 속성이 delay를 0으로 두고, 예전 셀렉터 특이도가 낮아 delay가 덮어씌워지지 않았음.
125	   * 반드시 .is-open.is-drawer-text-reveal 아래에서만 delay를 지정 (특이도 > 위 단축 규칙의 암시적 delay).
126	   */
127	  &.is-open.is-drawer-text-reveal {
128	    @for $i from 1 through 14 {
129	      #{$root}__gnb-item:nth-child(#{$i}) #{$root}__reveal-inner {
130	        transition-delay: ($i - 1) * $drawer-reveal-stagger;
131	      }
132	    }
133	
134	    $drawer-address-base: 0.48s;
135	
136	    #{$root}__address-block:nth-child(1) #{$root}__reveal-inner {
137	      transition-delay: $drawer-address-base;
138	    }
139	
140	    #{$root}__address-block:nth-child(2) #{$root}__reveal-inner {
141	      transition-delay: $drawer-address-base + $drawer-reveal-stagger;
142	    }
143	
144	    #{$root}__address-block:nth-child(3) #{$root}__reveal-inner {
145	      transition-delay: $drawer-address-base + $drawer-reveal-stagger * 2;
146	    }
147	
148	    #{$root}__address-block:nth-child(4) #{$root}__reveal-inner {
149	      transition-delay: $drawer-address-base + $drawer-reveal-stagger * 3;
150	    }
151	
152	    #{$root}__address-block:nth-child(5) #{$root}__reveal-inner {
153	      transition-delay: $drawer-address-base + $drawer-reveal-stagger * 4;
154	    }
155	  }
156	
157	  &:not(.is-open) &__reveal-inner {
158	    transition-duration: 0.28s;
159	    transition-delay: 0s !important;
160	    transition-timing-function: ease-out;
161	  }
162	
163	  &__gnb-item > #{$root}__reveal {
164	    flex: 1 1 auto;
165	    min-width: 0;
166	    width: 100%;
167	  }
168	
169	  &__gnb-item:not(&__gnb-item--has-sub)
170	    > #{$root}__reveal
171	    > #{$root}__reveal-inner {
172	    display: flex;
173	    flex-wrap: wrap;
174	    align-items: center;
175	    gap: var(--gutter-sm);
176	  }
177	
178	  @media (prefers-reduced-motion: reduce) {
179	    #{$root}__reveal-inner {
180	      transition: none !important;
181	    }
182	
183	    &.is-open.is-drawer-text-reveal #{$root}__reveal-inner {
184	      transform: none !important;
185	      opacity: 1 !important;
186	    }
187	  }
188	
