276	
277	    // is-active 시 코너 브라켓 표시 (실 요소, 마그네틱과 동일 8-path 형식)
278	    &.is-active {
279	      color: var(--clr-text-title);
280	      text-shadow: none;
281	    }
282	  }
283	
284	  // GNB/LNB 내 마스킹 텍스트 — 인라인 유지 (gnb → lnb → address 순 노출)
285	  &__gnb-link .masking-text,
286	  &__gnb-sub-link .masking-text {
287	    display: inline-block;
288	    vertical-align: middle;
289	  }
290	
291	  // GNB 배지(작품 수) — 필요 시 표시
292	  &__badge {
293	    position: relative;
294	    display: inline-flex;
295	    align-items: center;
296	    justify-content: flex-start;
297	    min-height: fluid(40, 46);
298	    padding: fluid(8, 10) fluid(12, 14);
299	    border: 1px solid var(--clr-border-weak);
300	    background: transparent;
301	    --corner-bracket-size: 10px;
302	    color: var(--clr-text-desc);
303	    font-family: var(--family-en-title);
304	    @include font("f-body-3");
305	    font-weight: 500;
306	    transition:
307	      border-color var(--transition-default),
308	      background-color var(--transition-default),
309	      transform var(--transition-default),
310	      color var(--transition-default);
311	
312	    @include mq(md) {
313	      display: none;
314	    }
315	  }
316	
317	  &__badge-inner {
318	    position: relative;
319	    z-index: 1;
320	    display: inline-flex;
321	    align-items: center;
322	    gap: fluid(10, 12);
323	    padding: fluid(4, 5) fluid(6, 8);
324	  }
325	
326	  &__badge-corner {
327	    color: color-mix(in srgb, var(--clr-border-strong) 82%, transparent);
328	  }
329	
330	  &__badge-rect {
331	    position: relative;
332	    flex-shrink: 0;
333	  }
334	
335	  &__badge-count {
336	    display: inline-block;
337	    color: var(--clr-text-title);
338	    line-height: 1;
339	    letter-spacing: 0.04em;
340	    white-space: nowrap;
341	    text-shadow: 0 0 18px
342	      color-mix(in srgb, var(--clr-white-100) 12%, transparent);
343	  }
344	
345	  &__gnb-item:hover &__badge,
346	  &__gnb-item:focus-within &__badge {
347	    border-color: var(--clr-border-default);
348	    background-color: color-mix(
349	      in srgb,
350	      var(--clr-border-weak) 12%,
351	      transparent
352	    );
353	    transform: translateY(-2px);
354	    color: var(--clr-text-title);
355	  }
356	
357	  &__gnb-item:hover &__badge-rect span,
358	  &__gnb-item:focus-within &__badge-rect span {
359	    opacity: 0.9;
360	  }
361	
362	  // ---------------------------------------------------------------------------
363	  // LNB (서브메뉴, INSIDE 하단 Insight / News / Notice 등)
364	  // ---------------------------------------------------------------------------
365	  &__submenu {
366	    margin-top: var(--gutter-md);
367	  }
368	
369	  &__lnb {
370	    display: flex;
371	    flex-wrap: wrap;
372	    gap: var(--gutter-sm) var(--gutter-md);
373	  }
374	
375	  &__lnb-item {
376	    display: inline-flex;
377	  }
378	
379	  &__lnb-link {
380	    display: inline-flex;
381	    align-items: center;
382	    color: var(--clr-text-desc);
383	    font-family: var(--family-en-title);
384	    @include font("f-body-3");
385	    font-weight: 400;
386	
387	    transition: color var(--transition-fast);
388	
389	    &:hover {
390	      color: var(--clr-text-title);
391	    }
392	
393	    &.is-active {
394	      color: var(--clr-text-title);
395	      font-weight: 500;
396	    }
397	  }
398	
