34	class BrowserClipboardPort implements ClipboardPort {
35	  async writeText(text: string): Promise<void> {
36	    if (navigator.clipboard?.writeText) {
37	      await navigator.clipboard.writeText(text);
38	      return;
39	    }
40	    BrowserClipboardPort.legacyCopy(text);
41	  }
42	
43	  private static legacyCopy(text: string): void {
44	    const textarea = document.createElement("textarea");
45	    textarea.value = text;
46	    textarea.setAttribute("readonly", "true");
47	    textarea.style.position = "fixed";
48	    textarea.style.top = "-9999px";
49	    document.body.appendChild(textarea);
50	    textarea.select();
51	    const ok = document.execCommand("copy");
52	    document.body.removeChild(textarea);
53	    if (!ok) throw new Error("copy failed");
54	  }
55	}
