297	  private flush(): void {
298	    const { x0, y0, x1, y1, L, p } = this.H;
299	    const visible = p > 0.001;
300	
301	    MAGNETIC_CORNER_ARM_IDS.forEach((id, i) => {
302	      const el = this.arms[id];
303	      if (!visible) {
304	        el.setAttribute("visibility", "hidden");
305	        this.cache[id + "d"] = "";
306	        this.cache[id + "da"] = "";
307	        this.cache[id + "do"] = "";
308	        return;
309	      }
310	
311	      el.removeAttribute("visibility");
312	      const off = +(L * (1 - p)).toFixed(3);
313	      const len = +L.toFixed(3);
314	      const defs: [number, number, number, number][] = [
315	        [x0, y0, x0 + L, y0],
316	        [x0, y0, x0, y0 + L],
317	        [x1, y0, x1 - L, y0],
318	        [x1, y0, x1, y0 + L],
319	        [x0, y1, x0 + L, y1],
320	        [x0, y1, x0, y1 - L],
321	        [x1, y1, x1 - L, y1],
322	        [x1, y1, x1, y1 - L],
323	      ];
324	      const [ax, ay, bx, by] = defs[i] as [number, number, number, number];
325	      const d = `M ${+ax.toFixed(2)},${+ay.toFixed(2)} L ${+bx.toFixed(2)},${+by.toFixed(2)}`;
326	      const lenStr = String(len);
327	      const offStr = String(off);
328	      if (this.cache[id + "d"] !== d) {
329	        el.setAttribute("d", d);
330	        this.cache[id + "d"] = d;
331	      }
332	      if (this.cache[id + "da"] !== lenStr) {
333	        el.setAttribute("stroke-dasharray", lenStr);
334	        this.cache[id + "da"] = lenStr;
335	      }
336	      if (this.cache[id + "do"] !== offStr) {
337	        el.setAttribute("stroke-dashoffset", offStr);
338	        this.cache[id + "do"] = offStr;
339	      }
340	    });
341	  }
