350	      cx: r.left + r.width / 2,
351	      cy: r.top + r.height / 2,
352	      hw: r.width / 2,
353	      hh: r.height / 2,
354	      x0: r.left - g,
355	      y0: r.top - g,
356	      x1: r.right + g,
357	      y1: r.bottom + g,
358	      L:
359	        s >= MAGNETIC_CORNER_SIZE_THRESHOLD
360	          ? MAGNETIC_CORNER_ARM_FIXED
361	          : Math.max(MAGNETIC_CORNER_ARM_MIN, s * MAGNETIC_CORNER_ARM_RATIO_SMALL),
