414	  private bind(elements: NodeListOf<Element>): void {
415	    const { pull, pullText, cornerFollow } = this.cfg;
416	    const g = this.gsap;
417	
418	    elements.forEach((el) => {
419	      const target = el as HTMLElement;
420	      const txt = target.querySelector<HTMLElement>(MAGNETIC_CORNER_TEXT_SELECTOR) ?? null;
421	
422	      target.addEventListener("mouseenter", () => {
