450	            return;
451	          }
452	          const b = this.rectCache.get(p.el);
453	          if (!b) return;
454	          const rx = (p.x - b.cx) / b.hw;
455	          const ry = (p.y - b.cy) / b.hh;
456	          const bx = rx * b.hw * pull;
457	          const by = ry * b.hh * pull;
458	          
