471	              x: bx * (pullText / pull),
472	              y: by * (pullText / pull),
473	              duration: 0.25,
474	              ease: "power2.out",
475	              overwrite: "auto",
476	            });
477	          this.hoverTween?.kill?.();
478	          this.hoverTween = this.gsapTo(this.H, {
479	            x0: b.x0 + bxCorner,
480	            y0: b.y0 + byCorner,
481	            x1: b.x1 + bxCorner,
482	            y1: b.y1 + byCorner,
483	            duration: 0.35,
484	            ease: "power2.out",
485	            onUpdate: () => (this.dirty = true),
486	            overwrite: "auto",
487	          });
488	        });
489	      });
490	    });
491	  }
