522	export function updateStaticCornerSizes(root?: ParentNode | null): void {
523	  if (typeof document === "undefined") return;
524	  const scope = root ?? document;
525	  const brackets = scope.querySelectorAll<HTMLElement>(".no-corner-bracket");
526	  if (brackets.length === 0) return;
527	  brackets.forEach((el) => {
528	    const parent = el.parentElement;
529	    if (!parent) return;
530	    const r = parent.getBoundingClientRect();
531	    const s = Math.min(r.width, r.height);
532	    const size =
533	      s >= CORNER_SIZE_THRESHOLD
534	        ? CORNER_BRACKET_SIZE_FIXED
535	        : CORNER_BRACKET_SIZE_MIN;
536	    el.style.setProperty("--corner-bracket-size", `${size}px`);
537	  });
538	
539	  if (!staticCornerResizeBound) {
540	    staticCornerResizeBound = true;
541	    window.addEventListener("resize", handleStaticCornerResize, { passive: true });
542	  }
543	}
